import { render } from '@solidjs/web';
import { createSignal, onSettled, Show } from 'solid-js';

const [ticks, setTicks] = createSignal(0);

function Timer() {
  let input;
  setInterval(() => setTicks((n) => n + 1), 1000);

  return (
    <p>
      Lap label: <input />
    </p>
  );
}

function App() {
  const [running, setRunning] = createSignal(true);

  return (
    <>
      <label>
        <input
          type="checkbox"
          checked={running()}
          onChange={(event) => setRunning(event.currentTarget.checked)}
        />{' '}
        Show the timer
      </label>
      <p>Total ticks: {ticks()}</p>
      <Show when={running()}>
        <Timer />
      </Show>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, onSettled, Show } from 'solid-js';

const [ticks, setTicks] = createSignal(0);

function Timer() {
  let input;

  onSettled(() => {
    input.focus();
    const timer = setInterval(() => setTicks((n) => n + 1), 1000);
    return () => clearInterval(timer);
  });

  return (
    <p>
      Lap label: <input ref={input} />
    </p>
  );
}

function App() {
  const [running, setRunning] = createSignal(true);

  return (
    <>
      <label>
        <input
          type="checkbox"
          checked={running()}
          onChange={(event) => setRunning(event.currentTarget.checked)}
        />{' '}
        Show the timer
      </label>
      <p>Total ticks: {ticks()}</p>
      <Show when={running()}>
        <Timer />
      </Show>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
